import type { Question } from '../../lib/types'
export const sqs_sns_eventbridge_questions: Question[] = [
  { id: 'd2-msg-001', domain: 2, topics: ['SQS', 'decoupling', 'standard queue'], type: 'single', stem: 'A producer sends messages faster than the consumer processes them. What SQS behavior handles this mismatch?', options: [{ id: 'A', text: 'SQS blocks the producer when the queue is full until consumers drain capacity' }, { id: 'B', text: 'SQS acts as a buffer — messages accumulate in the queue while consumers process at their own rate' }, { id: 'C', text: 'SQS automatically scales consumer EC2 instances when queue depth exceeds a threshold' }, { id: 'D', text: 'SQS rejects messages above a configurable depth limit to prevent queue overflow' }], correct: ['B'], explanation: 'SQS is a durable message buffer. Producers send at any rate; the queue stores messages for up to 14 days. Consumers process at their own rate — the queue absorbs the speed difference (buffering / decoupling pattern).', distractors: { A: 'SQS does not block producers — it accepts messages up to the per-queue limit (120,000 in-flight for Standard).', C: 'SQS does not directly scale consumers — integrate with Auto Scaling using CloudWatch metrics on queue depth.', D: 'SQS standard queues do not reject messages at a configurable depth — FIFO queues have a limit but standard queues scale.' } },
  { id: 'd2-msg-002', domain: 2, topics: ['SQS', 'visibility timeout'], type: 'single', stem: 'A Lambda function receives an SQS message but takes 5 minutes to process. Visibility timeout is 30 seconds. Problem?', options: [{ id: 'A', text: 'Lambda will time out — Lambda maximum execution time is 5 minutes' }, { id: 'B', text: 'The message becomes visible again after 30 seconds and another consumer processes the duplicate' }, { id: 'C', text: 'SQS deletes the message after 30 seconds if not acknowledged' }, { id: 'D', text: 'Lambda automatically extends the visibility timeout when processing takes longer than configured' }], correct: ['B'], explanation: 'Visibility timeout: while a consumer processes a message, it is invisible to other consumers. If not deleted before the timeout (30s), the message becomes visible again — another consumer picks it up causing duplicate processing.', distractors: { A: 'Lambda timeout is configurable up to 15 minutes — the issue is SQS visibility timeout, not Lambda timeout.', C: 'SQS does not delete messages on visibility timeout expiry — it makes them visible again (re-queues).', D: 'Lambda does not automatically extend visibility timeout — the consumer must call ChangeMessageVisibility if processing takes longer.' } },
  { id: 'd2-msg-003', domain: 2, topics: ['SQS', 'DLQ'], type: 'single', stem: 'An SQS message fails processing 5 times. What prevents it from blocking the queue indefinitely?', options: [{ id: 'A', text: 'SQS automatically deletes messages after 5 failed attempts' }, { id: 'B', text: 'Configure a Dead Letter Queue (DLQ) with MaxReceiveCount=5 — messages exceeding receive attempts move to DLQ' }, { id: 'C', text: 'Set message retention to 1 hour — failed messages expire before they can block the queue' }, { id: 'D', text: 'Enable long polling — it skips messages that have failed more than a configured number of times' }], correct: ['B'], explanation: 'DLQ with MaxReceiveCount: when a message is received more than MaxReceiveCount times without deletion, it is moved to the DLQ. Preserves the problematic message for analysis without blocking the main queue.', distractors: { A: 'SQS does not auto-delete after failures — messages stay in the queue until deleted or retention expires.', C: 'Short retention causes data loss — DLQ is for analysis, not expiry.', D: 'Long polling changes how consumers wait for messages — it does not skip or filter by failure count.' } },
  { id: 'd2-msg-004', domain: 2, topics: ['SQS', 'FIFO', 'ordering'], type: 'single', stem: 'An e-commerce system must process payment events in the exact order they were submitted. Queue type?', options: [{ id: 'A', text: 'SQS Standard — high throughput with best-effort ordering for all message types' }, { id: 'B', text: 'SQS FIFO — guarantees exactly-once processing and strict first-in-first-out ordering' }, { id: 'C', text: 'SQS Standard with message sequencing attributes for client-side ordering' }, { id: 'D', text: 'SNS FIFO — ordered notification delivery for payment events' }], correct: ['B'], explanation: 'SQS FIFO queue: guaranteed ordering, exactly-once processing, and deduplication. For payment events, strict ordering prevents reversing transactions. Throughput limited to 3,000 TPS with batching.', distractors: { A: 'Standard queue provides best-effort ordering — it may deliver messages out of order for payment processing.', C: 'Client-side ordering adds application complexity and does not guarantee server-side ordering.', D: 'SNS FIFO is for fan-out with ordering — the actual ordered processing queue should be SQS FIFO.' } },
  { id: 'd2-msg-005', domain: 2, topics: ['SQS', 'long polling'], type: 'single', stem: 'An SQS consumer polls the queue and receives empty responses 90% of the time. Cost and efficiency issue. Fix?', options: [{ id: 'A', text: 'Increase message retention to reduce polling frequency' }, { id: 'B', text: 'Enable long polling (WaitTimeSeconds=20) — consumer waits up to 20 seconds for messages before returning empty' }, { id: 'C', text: 'Increase the number of consumers — more consumers reduce empty responses per consumer' }, { id: 'D', text: 'Enable SQS visibility timeout reduction — reduces idle time between polls' }], correct: ['B'], explanation: 'Long polling: ReceiveMessage waits up to 20 seconds for messages to arrive before returning. Reduces empty responses, reduces API calls, reduces cost, and decreases message latency compared to short polling.', distractors: { A: 'Message retention affects how long messages stay in the queue — it does not reduce empty polls.', C: 'More consumers still make the same proportion of empty API calls per consumer.', D: 'Visibility timeout controls in-flight message re-availability — it does not address empty poll frequency.' } },
  { id: 'd2-msg-006', domain: 2, topics: ['SQS', 'message deduplication'], type: 'single', stem: 'A producer sends duplicate messages to an SQS FIFO queue. What prevents duplicate processing?', options: [{ id: 'A', text: 'SQS Standard queues have built-in deduplication using message ID hashing' }, { id: 'B', text: 'SQS FIFO deduplication: provide a MessageDeduplicationId; same ID within 5 minutes discards duplicates' }, { id: 'C', text: 'Enable SQS at-least-once delivery — it automatically detects and discards duplicate messages' }, { id: 'D', text: 'The consumer must implement idempotent processing — SQS does not perform deduplication' }], correct: ['B'], explanation: 'SQS FIFO with content-based deduplication or explicit MessageDeduplicationId: if the same ID is received within a 5-minute window, the duplicate is silently discarded — exactly-once delivery.', distractors: { A: 'Standard queues use at-least-once delivery — they do not deduplicate. FIFO queues do.', C: 'At-least-once delivery means duplicates can be delivered — it is the opposite of deduplication.', D: 'SQS FIFO performs server-side deduplication — consumers do not need to handle this for FIFO queues.' } },
  { id: 'd2-msg-007', domain: 2, topics: ['SNS', 'fan-out'], type: 'single', stem: 'One event must be processed by 3 different applications simultaneously. Design pattern?', options: [{ id: 'A', text: 'Create 3 SQS queues and send the event to all 3 queues separately from the producer' }, { id: 'B', text: 'SNS topic with 3 SQS queue subscriptions — SNS delivers the event to all 3 queues simultaneously' }, { id: 'C', text: 'SQS with 3 consumer groups — each consumer group reads from the same queue independently' }, { id: 'D', text: 'EventBridge bus with 3 rules targeting 3 separate Lambda functions for processing' }], correct: ['B'], explanation: 'SNS fan-out: producer sends one message to an SNS topic, which delivers to all 3 SQS subscriptions in parallel. Each application reads from its own queue — decoupled, resilient fan-out pattern.', distractors: { A: 'Sending to 3 queues separately creates producer-side coupling — SNS fan-out decouples the producer.', C: 'SQS does not support consumer groups — each message is consumed by one consumer in SQS.', D: 'EventBridge is also valid for fan-out — SNS+SQS is the classic messaging pattern for this use case.' } },
  { id: 'd2-msg-008', domain: 2, topics: ['SNS', 'message filtering'], type: 'single', stem: 'An SNS topic has 5 subscribers. Each subscriber should only receive messages matching its specific criteria. Solution?', options: [{ id: 'A', text: 'Create 5 separate SNS topics — one per subscriber to isolate message delivery' }, { id: 'B', text: 'SNS message filtering — each subscription has a filter policy that matches specific message attributes' }, { id: 'C', text: 'Use Lambda to inspect each SNS message and forward to the correct subscriber' }, { id: 'D', text: 'Add a MessageGroupId to each message — subscribers receive only their group' }], correct: ['B'], explanation: 'SNS filter policies: each subscription can have a JSON filter policy that matches on message attributes. Messages not matching the filter are not delivered to that subscription — no code needed.', distractors: { A: 'Separate topics add operational overhead — filter policies achieve per-subscriber filtering on a single topic.', C: 'Lambda routing adds latency and cost — filter policies are evaluated server-side by SNS.', D: 'MessageGroupId is an SQS FIFO concept for ordering — not SNS message filtering.' } },
  { id: 'd2-msg-009', domain: 2, topics: ['SQS', 'message delay'], type: 'single', stem: 'SQS messages should not be visible to consumers for the first 60 seconds after being sent. Configuration?', options: [{ id: 'A', text: 'Set message visibility timeout to 60 seconds' }, { id: 'B', text: 'Set message delay (Delay Seconds or Per-Message Delay) to 60 seconds' }, { id: 'C', text: 'Set the queue\'s WaitTimeSeconds to 60 seconds' }, { id: 'D', text: 'Set message retention to 60 seconds — messages expire before visibility begins' }], correct: ['B'], explanation: 'Message delay: when a message is sent to SQS, it is invisible to consumers for the configured delay period (0-15 minutes). Different from visibility timeout, which starts after a message is received.', distractors: { A: 'Visibility timeout applies after a consumer receives a message — delay applies before first receipt.', C: 'WaitTimeSeconds controls how long a receive call waits for messages — not message delivery delay.', D: 'Retention time controls how long messages are kept — short retention causes data loss, not delayed visibility.' } },
  { id: 'd2-msg-010', domain: 2, topics: ['EventBridge', 'rules', 'routing'], type: 'single', stem: 'An EventBridge rule should trigger a Lambda only when EC2 instance state changes to "stopped". Rule content filter?', options: [{ id: 'A', text: 'Trigger on all EC2 events — Lambda filters the state change inside the function' }, { id: 'B', text: 'Event pattern matching detail-type=EC2 Instance State-change Notification and detail.state=stopped' }, { id: 'C', text: 'Create a CloudWatch alarm on the EC2 state metric for stopped state' }, { id: 'D', text: 'EventBridge cannot filter on instance state — it triggers on all state changes' }], correct: ['B'], explanation: 'EventBridge event patterns: match on event source (aws.ec2), detail-type, and specific attributes within the detail object. Matching state=stopped ensures Lambda is invoked only for the stopped transition.', distractors: { A: 'Filtering inside Lambda invokes it unnecessarily for all state changes — EventBridge pattern matching avoids unnecessary invocations.', C: 'CloudWatch alarms are for metric thresholds — EC2 state changes are EventBridge events, not metrics.', D: 'EventBridge fully supports content filtering on any JSON attribute in the event — including state field values.' } },
  { id: 'd2-msg-011', domain: 2, topics: ['EventBridge', 'Scheduler'], type: 'single', stem: 'A Lambda function must run at 8 AM UTC every weekday. How?', options: [{ id: 'A', text: 'CloudWatch Events cron rule — triggers Lambda at the specified schedule' }, { id: 'B', text: 'EventBridge Scheduler with cron(0 8 ? * MON-FRI *) expression targeting Lambda' }, { id: 'C', text: 'Lambda reserved concurrency schedule — pre-warms Lambda at 8 AM for cold start reduction' }, { id: 'D', text: 'Both A and B — CloudWatch Events and EventBridge Scheduler both support cron scheduling' }], correct: ['D'], explanation: 'Both EventBridge (formerly CloudWatch Events) and EventBridge Scheduler support cron expressions. Scheduler adds one-time schedules and flexible time windows. Both deliver to Lambda on the defined schedule.', distractors: { A: 'CloudWatch Events (EventBridge rules) support cron but are correct only as part of the full answer.', B: 'EventBridge Scheduler is correct but incomplete — CloudWatch Events rules also support cron scheduling.', C: 'Lambda concurrency is not a scheduling mechanism — it controls how many concurrent invocations are permitted.' } },
  { id: 'd2-msg-012', domain: 2, topics: ['SQS', 'Lambda trigger'], type: 'single', stem: 'Lambda is triggered by SQS. How are messages batched when processed?', options: [{ id: 'A', text: 'Lambda processes one message per invocation — no batching' }, { id: 'B', text: 'Lambda receives a batch of up to 10,000 messages per invocation (configurable batch size)' }, { id: 'C', text: 'Lambda SQS trigger batches up to 10 messages by default (1-10,000 configurable)' }, { id: 'D', text: 'Lambda SQS batching is disabled by default — enable it in the Lambda trigger configuration' }], correct: ['C'], explanation: 'Lambda SQS event source mapping: default batch size is 10 messages (1-10,000 for Standard queues, 1-10 for FIFO). Lambda polls the queue and passes the batch as an array in the event object.', distractors: { A: 'Lambda processes batches — single message per invocation is configurable but not the default.', B: '10,000 is the maximum batch size — the default batch size is 10 messages.', D: 'Batching is enabled by default — the default batch size of 10 is applied automatically.' } },
  { id: 'd2-msg-013', domain: 2, topics: ['SNS', 'SQS', 'Lambda', 'fan-out reliability'], type: 'single', stem: 'An SNS topic delivers directly to Lambda. Lambda failures cause message loss. How to add a buffer for reliability?', options: [{ id: 'A', text: 'Enable SNS delivery retries — SNS retries failed Lambda invocations' }, { id: 'B', text: 'Add SQS queue between SNS and Lambda — SNS delivers to SQS, Lambda processes from SQS with DLQ' }, { id: 'C', text: 'Enable Lambda Destinations for failed invocations — routes failures to SQS' }, { id: 'D', text: 'Increase Lambda concurrency — prevents failures due to throttling' }], correct: ['B'], explanation: 'SNS → SQS → Lambda: SQS acts as a buffer. If Lambda fails, the message stays in SQS (visibility timeout re-queues it). DLQ catches persistent failures. SNS+SQS is more resilient than SNS directly to Lambda.', distractors: { A: 'SNS retries Lambda invocations but messages can still be lost after retry exhaustion — SQS provides durable buffering.', C: 'Lambda Destinations route async invocation results — not a buffer for incoming messages.', D: 'Higher concurrency reduces throttling — it does not protect against processing failures or Lambda crashes.' } },
  { id: 'd2-msg-014', domain: 2, topics: ['SQS', 'message size'], type: 'single', stem: 'SQS maximum message size is 256 KB. A payload of 10 MB must be processed. Solution?', options: [{ id: 'A', text: 'Split the payload into smaller SQS messages and reassemble in the consumer' }, { id: 'B', text: 'Extended Client Library: store payload in S3, send S3 reference in SQS message (S3 event pointer pattern)' }, { id: 'C', text: 'Use Kinesis Data Streams — it supports messages up to 1 MB per record' }, { id: 'D', text: 'Use SNS instead — SNS supports payloads up to 100 MB' }], correct: ['B'], explanation: 'Extended Client Library (Java/Python) or manual S3 pointer pattern: upload large payload to S3, send SQS message containing the S3 bucket/key reference. Consumer reads S3 reference from SQS, then downloads the full payload from S3.', distractors: { A: 'Splitting and reassembling adds complexity and ordering challenges — S3 pointer pattern is simpler.', C: 'Kinesis supports 1 MB per record — still insufficient for 10 MB. The S3 pointer pattern handles any size.', D: 'SNS maximum message size is 256 KB — same as SQS. SNS does not support 100 MB payloads.' } },
  { id: 'd2-msg-015', domain: 2, topics: ['EventBridge', 'custom events'], type: 'single', stem: 'An application must publish custom events to trigger downstream workflows. Which EventBridge configuration is needed?', options: [{ id: 'A', text: 'Use the default event bus — it accepts PutEvents API calls for all custom events' }, { id: 'B', text: 'Create a custom event bus — dedicated bus for application events, separate from AWS service events' }, { id: 'C', text: 'Both A and B — custom events can go to the default bus or a dedicated custom bus' }, { id: 'D', text: 'Events must go through CloudWatch — EventBridge does not accept application-published events' }], correct: ['C'], explanation: 'Custom events (via PutEvents API) can be published to the default event bus or a custom event bus. Custom buses isolate application events from AWS service events and enable cross-account publishing.', distractors: { A: 'Default bus works but is correct only as part of the full answer — custom buses are also an option.', B: 'Custom bus is correct but incomplete — default bus also accepts custom PutEvents calls.', D: 'EventBridge accepts application-published events via PutEvents — CloudWatch is not required.' } },
  { id: 'd2-msg-016', domain: 2, topics: ['SQS', 'visibility timeout', 'ChangeMessageVisibility'], type: 'single', stem: 'A consumer determines mid-processing that it needs 10 more minutes to finish. Visibility timeout is 5 minutes. Solution?', options: [{ id: 'A', text: 'Delete and re-send the message with a 10-minute delay' }, { id: 'B', text: 'Call ChangeMessageVisibility to extend the visibility timeout before it expires' }, { id: 'C', text: 'Set a longer queue-level visibility timeout to cover all processing scenarios' }, { id: 'D', text: 'Return the message to the queue by calling NackMessage — allows re-processing with extended time' }], correct: ['B'], explanation: 'ChangeMessageVisibility extends the visibility timeout for a specific message in flight. Call it before the current timeout expires to prevent the message from becoming visible and being picked up by another consumer.', distractors: { A: 'Delete and re-send loses the current processing state — ChangeMessageVisibility extends without interruption.', C: 'Queue-level timeout applies to all messages — it should not be set to the maximum processing time.', D: 'NackMessage does not exist in SQS — ChangeMessageVisibility is the correct API.' } },
  { id: 'd2-msg-017', domain: 2, topics: ['SNS', 'delivery protocols'], type: 'single', stem: 'An SNS topic must notify a mobile app, an email address, and an HTTP webhook simultaneously. Protocol support?', options: [{ id: 'A', text: 'SNS only supports SQS and Lambda as subscription protocols' }, { id: 'B', text: 'SNS supports email, HTTP/HTTPS, SQS, Lambda, mobile push, SMS, and Kinesis Data Firehose' }, { id: 'C', text: 'SNS supports email and HTTP but not mobile push — use Firebase for mobile notifications' }, { id: 'D', text: 'SNS supports up to 3 protocol types per topic — mobile, email, and HTTP each require separate topics' }], correct: ['B'], explanation: 'SNS subscription protocols: email, email-JSON, HTTP, HTTPS, SQS, Lambda, SMS, mobile push (APNs, FCM, ADM, Baidu), and Kinesis Data Firehose. A single topic can have subscribers on all protocols simultaneously.', distractors: { A: 'SNS supports many more protocols than just SQS and Lambda.', C: 'SNS natively supports mobile push via APNs (iOS) and FCM (Android) — Firebase is not required.', D: 'A single topic has no protocol type limit — all protocols can be active simultaneously.' } },
  { id: 'd2-msg-018', domain: 2, topics: ['EventBridge', 'archive and replay'], type: 'single', stem: 'An EventBridge rule was misconfigured and events were lost. How to reprocess past events?', options: [{ id: 'A', text: 'Events cannot be replayed — EventBridge does not store past events by default' }, { id: 'B', text: 'Enable EventBridge Archive — replays events from the archive for a specified time window' }, { id: 'C', text: 'Use CloudTrail to retrieve past EventBridge events for reprocessing' }, { id: 'D', text: 'Query the EventBridge event history in the console — replay from the event list' }], correct: ['B'], explanation: 'EventBridge Archive: when enabled, events are stored in the archive. EventBridge Replay creates a new replay run that re-delivers archived events to the event bus — rules process them as if they are new events.', distractors: { A: 'EventBridge archives events if Archive is configured — events are stored for replay.', C: 'CloudTrail records API calls — not event data from the EventBridge bus.', D: 'EventBridge console does not have a native replay from event history — Archive must be configured first.' } },
  { id: 'd2-msg-019', domain: 2, topics: ['SQS', 'Lambda', 'batch failure'], type: 'single', stem: 'Lambda processes SQS batch of 10 messages. 2 messages fail. How to prevent the entire batch from being re-queued?', options: [{ id: 'A', text: 'Configure Lambda to process messages one at a time — no batch failures with batch size 1' }, { id: 'B', text: 'Return the 2 failed message IDs in batchItemFailures response — only failed messages become visible again' }, { id: 'C', text: 'Delete successful messages manually in the Lambda function before returning' }, { id: 'D', text: 'Set maxBatchingWindow to 0 — prevents batch accumulation so fewer messages fail at once' }], correct: ['B'], explanation: 'Lambda SQS partial batch response: return a reportBatchItemFailures response with the messageId of failed messages. SQS only re-queues those specific messages — the 8 successful messages are deleted automatically.', distractors: { A: 'Batch size 1 eliminates batching benefits — partial batch failure response handles mixed results efficiently.', C: 'Manual deletion adds code complexity and error-handling burden — partial batch response is the built-in mechanism.', D: 'maxBatchingWindow controls buffering time before Lambda is invoked — it does not address per-message failure handling.' } },
  { id: 'd2-msg-020', domain: 2, topics: ['SQS', 'Standard vs FIFO', 'throughput'], type: 'single', stem: 'An application sends 5,000 messages per second to SQS. FIFO queue limit is 3,000 TPS. What if ordering is not required?', options: [{ id: 'A', text: 'Use SQS FIFO with multiple message group IDs to increase throughput beyond 3,000 TPS' }, { id: 'B', text: 'Use SQS Standard — near-unlimited throughput with at-least-once delivery, no ordering guarantee' }, { id: 'C', text: 'Use multiple SQS FIFO queues — each queue handles 3,000 TPS for total 5,000 TPS' }, { id: 'D', text: 'SQS cannot handle 5,000 TPS — use Kinesis Data Streams for high-throughput messaging' }], correct: ['B'], explanation: 'SQS Standard: nearly unlimited throughput (at-least-once delivery, best-effort ordering). For 5,000 TPS without ordering requirement, Standard is the correct choice — FIFO\'s 3,000 TPS limit is unnecessary complexity.', distractors: { A: 'Multiple message group IDs in FIFO increase throughput per group — but FIFO has a 300 TPS per group limit (3,000 TPS with high-throughput mode).', C: 'Multiple FIFO queues add complexity — Standard queue handles 5,000+ TPS natively.', D: 'SQS Standard supports very high throughput — it is not limited to 5,000 TPS.' } },
  { id: 'd2-msg-021', domain: 2, topics: ['SNS', 'FIFO', 'ordering'], type: 'single', stem: 'A financial system publishes events to SNS and consumes them with multiple subscribers in strict order. Solution?', options: [{ id: 'A', text: 'Standard SNS topic with SQS FIFO subscribers — consumer-side ordering' }, { id: 'B', text: 'SNS FIFO topic with SQS FIFO subscribers — maintains message order from publisher to consumer' }, { id: 'C', text: 'SNS Standard topic — ordering is maintained by message timestamp attributes' }, { id: 'D', text: 'Kinesis Data Streams — shards maintain strict ordering with exactly-once delivery' }], correct: ['B'], explanation: 'SNS FIFO topic + SQS FIFO subscribers: messages are published and delivered in strict FIFO order. SNS FIFO supports deduplication and ordering from source to destination — end-to-end order preservation.', distractors: { A: 'Standard SNS does not guarantee ordering to subscribers — FIFO ordering starts at the SNS level.', C: 'Timestamp-based ordering is client-side logic — SNS does not sort messages by timestamp.', D: 'Kinesis maintains shard-level ordering — but SNS FIFO + SQS FIFO is the managed messaging solution for this pattern.' } },
  { id: 'd2-msg-022', domain: 2, topics: ['EventBridge', 'cross-account'], type: 'single', stem: 'A central monitoring account must receive EventBridge events from 10 separate application accounts. How?', options: [{ id: 'A', text: 'Create VPC peering between all accounts — EventBridge events route over private connections' }, { id: 'B', text: 'Create a custom event bus in the monitoring account; add resource policy allowing source accounts to publish' }, { id: 'C', text: 'Enable CloudTrail in all accounts and aggregate to the monitoring account' }, { id: 'D', text: 'Each application account polls the monitoring account event bus for events' }], correct: ['B'], explanation: 'EventBridge cross-account: each application account adds an EventBridge rule targeting the monitoring account\'s custom event bus. The custom bus has a resource policy allowing PutEvents from the source account IDs.', distractors: { A: 'EventBridge events are API-based — VPC peering is for network-level connectivity, not EventBridge routing.', C: 'CloudTrail aggregates API logs — not EventBridge application events.', D: 'EventBridge is push-based — there is no polling mechanism between event buses.' } },
  { id: 'd2-msg-023', domain: 2, topics: ['SQS', 'Lambda', 'concurrency'], type: 'single', stem: 'SQS triggers Lambda. 1,000 messages arrive simultaneously. How does Lambda scaling work?', options: [{ id: 'A', text: 'Lambda processes 1 batch at a time — maximum 1 concurrent Lambda execution per SQS queue' }, { id: 'B', text: 'Lambda scales to process multiple batches concurrently — one Lambda execution per 5 messages polled' }, { id: 'C', text: 'Lambda SQS event source scales to maximum 1,000 concurrent executions per queue by default' }, { id: 'D', text: 'Lambda scales in steps: 5 concurrent executions initially, increases by 5 every minute until capacity is reached' }], correct: ['B'], explanation: 'Lambda SQS scaling: Lambda adds 60 concurrent executions per minute (burst limit) up to the account concurrency limit. It polls the queue with 5 pollers initially, scaling to more as the queue depth grows.', distractors: { A: 'Lambda processes multiple batches concurrently — one execution per queue is not correct.', C: '1,000 per queue is not a hard limit — concurrency scales up to the Lambda account limit.', D: 'The initial burst is up to 3,000 concurrent (for most regions), not 5. Step scaling is 500/minute, not 5.' } },
  { id: 'd2-msg-024', domain: 2, topics: ['SNS', 'HTTPS', 'subscription confirmation'], type: 'single', stem: 'An SNS subscription is created for an HTTPS endpoint. The endpoint is not receiving messages. Root cause?', options: [{ id: 'A', text: 'SNS delivers immediately upon subscription creation — check application logs for 403 errors' }, { id: 'B', text: 'SNS sends a subscription confirmation request first; the endpoint must confirm by visiting the SubscribeURL' }, { id: 'C', text: 'HTTPS endpoints require SSL certificate validation — self-signed certificates are rejected' }, { id: 'D', text: 'SNS HTTPS delivery has 24-hour delay for DNS propagation of the endpoint' }], correct: ['B'], explanation: 'SNS HTTPS subscription confirmation: SNS sends a POST with a SubscribeURL to the endpoint. The application must make a GET request to the SubscribeURL to confirm. Until confirmed, no messages are delivered.', distractors: { A: 'Messages are not delivered before confirmation — the confirmation step is required first.', C: 'SSL certificate validation is a factor but the primary reason for no messages is pending confirmation.', D: 'There is no 24-hour DNS delay — the confirmation handshake must be completed by the endpoint.' } },
  { id: 'd2-msg-025', domain: 2, topics: ['EventBridge', 'event bus', 'rule target limit'], type: 'single', stem: 'An EventBridge rule must trigger 10 different targets when an event matches. Limit?', options: [{ id: 'A', text: 'Maximum 1 target per rule — create 10 separate rules for 10 targets' }, { id: 'B', text: 'Maximum 5 targets per rule — create 2 rules for 10 targets' }, { id: 'C', text: 'Maximum 5 targets per rule — but the rule can target an SNS topic that fans out to all 10' }, { id: 'D', text: 'Up to 5 targets per rule (default) — increase to 300 via Service Quotas' }], correct: ['D'], explanation: 'EventBridge supports up to 5 targets per rule by default. The limit can be increased to 300 via Service Quotas. For the 10-target requirement, request a quota increase or use SNS fan-out from one target.', distractors: { A: '10 separate rules for 10 targets works but is operationally unnecessary — increasing the target quota is the right approach.', B: 'The limit is 5 targets by default, correct — but increasing via Service Quotas is the best answer.', C: 'SNS fan-out is a valid workaround but adding Service Quotas is more direct.' } },
  { id: 'd2-msg-026', domain: 2, topics: ['SQS', 'security', 'encryption'], type: 'single', stem: 'SQS messages contain PII and must be encrypted at rest. Configuration?', options: [{ id: 'A', text: 'SQS encrypts all messages in transit over HTTPS — no additional encryption configuration needed' }, { id: 'B', text: 'Enable Server-Side Encryption (SSE) on the SQS queue using an SQS-managed key or AWS KMS CMK' }, { id: 'C', text: 'Encrypt the message body in the application before sending — SQS does not provide at-rest encryption' }, { id: 'D', text: 'Use SQS with VPC endpoints — VPC encryption protects messages at rest' }], correct: ['B'], explanation: 'SQS SSE: enable at the queue level using the SQS-managed key (SSE-SQS) for no-cost encryption, or a KMS CMK for audit trail and key rotation control. Encrypts messages stored in SQS.', distractors: { A: 'HTTPS encrypts transit — SSE-SQS is needed for at-rest encryption in the SQS storage layer.', C: 'SQS provides server-side at-rest encryption — client-side encryption is optional additional protection.', D: 'VPC endpoints route SQS traffic within AWS private network — they do not encrypt messages stored in SQS.' } },
  { id: 'd2-msg-027', domain: 2, topics: ['EventBridge', 'Pipes'], type: 'single', stem: 'SQS messages must be filtered, enriched via Lambda, and forwarded to EventBridge. Minimal code solution?', options: [{ id: 'A', text: 'EventBridge Pipes — managed pipeline connecting SQS source to EventBridge target with filtering and enrichment steps' }, { id: 'B', text: 'Lambda function that reads SQS, applies filters, calls enrichment API, then PutEvents to EventBridge' }, { id: 'C', text: 'Step Functions workflow orchestrating SQS polling, filtering Lambda, and EventBridge PutEvents' }, { id: 'D', text: 'CloudFormation custom resource that bridges SQS to EventBridge with enrichment logic' }], correct: ['A'], explanation: 'EventBridge Pipes: point-to-point integrations between event sources (SQS, DynamoDB, Kinesis) and targets. Built-in filtering, optional enrichment (Lambda, Step Functions), and target delivery — no custom code needed.', distractors: { B: 'Lambda-based solution works but requires writing and maintaining code — Pipes achieves this without custom code.', C: 'Step Functions adds orchestration overhead — Pipes provides the same pipeline with less operational complexity.', D: 'CloudFormation custom resources are for infrastructure provisioning — not event routing pipelines.' } },
  { id: 'd2-msg-028', domain: 2, topics: ['SQS', 'Lambda', 'DLQ placement'], type: 'single', stem: 'Lambda processes SQS messages. Failed messages should go to a DLQ for analysis. Where should the DLQ be configured?', options: [{ id: 'A', text: 'On the Lambda function — Lambda DLQ receives failed async invocations' }, { id: 'B', text: 'On the SQS source queue — SQS DLQ receives messages that exceed MaxReceiveCount' }, { id: 'C', text: 'On the EventBridge rule — EventBridge DLQ receives undelivered events' }, { id: 'D', text: 'On both Lambda and SQS — Lambda DLQ handles invocation failures; SQS DLQ handles receive failures' }], correct: ['B'], explanation: 'For Lambda triggered by SQS: configure the DLQ on the SQS queue. When a batch fails MaxReceiveCount times, the messages move to the SQS DLQ. Lambda DLQ is for async invocations (not SQS-triggered sync processing).', distractors: { A: 'Lambda DLQ handles async invocation failures (EventBridge, SNS) — not SQS-triggered synchronous Lambda.', C: 'EventBridge DLQ handles events that couldn\'t be delivered to a target — not SQS message processing failures.', D: 'For SQS-triggered Lambda, only the SQS queue DLQ is relevant — Lambda DLQ does not apply to SQS trigger mode.' } },
  { id: 'd2-msg-029', domain: 2, topics: ['SNS', 'SMS', 'mobile push'], type: 'single', stem: 'An SNS application message must reach 500,000 mobile users via push notifications. Configuration?', options: [{ id: 'A', text: 'Create 500,000 individual SNS topics — one per user' }, { id: 'B', text: 'Register device tokens as SNS platform endpoints; publish to each endpoint or use SNS topics with endpoint subscriptions' }, { id: 'C', text: 'Send 500,000 SMS messages via SNS — SMS reaches all mobile devices regardless of app installation' }, { id: 'D', text: 'Use SES instead of SNS — SES is better for high-volume mobile notification delivery' }], correct: ['B'], explanation: 'SNS mobile push: register each device token as a platform endpoint (APNs for iOS, FCM for Android). Publish directly to endpoint ARNs for targeted delivery. Use SNS topics for segment-based broadcast.', distractors: { A: 'One topic per user is operationally unmanageable — use platform endpoints for device-level addressing.', C: 'SMS requires a phone number — push notifications require app installation and device token registration.', D: 'SES is for email — not mobile push notifications.' } },
  { id: 'd2-msg-030', domain: 2, topics: ['SQS', 'throughput', 'batching'], type: 'single', stem: 'A consumer processes SQS messages individually, saturating at 100 messages/sec. How to increase throughput?', options: [{ id: 'A', text: 'Increase SQS visibility timeout — longer visibility reduces re-processing overhead' }, { id: 'B', text: 'Use SendMessageBatch and ReceiveMessage with batch size 10 — up to 10x the API throughput' }, { id: 'C', text: 'Enable SQS long polling — reduces empty responses and increases effective throughput' }, { id: 'D', text: 'Switch to SQS FIFO — FIFO has higher per-consumer throughput than Standard' }], correct: ['B'], explanation: 'Batch operations: ReceiveMessage (up to 10 messages) and DeleteMessageBatch (up to 10 deletions) process messages in bulk. API call count is reduced by up to 10x — processing throughput increases proportionally.', distractors: { A: 'Visibility timeout affects in-flight message availability — it does not increase processing throughput.', C: 'Long polling reduces empty responses (cost efficiency) — it does not directly increase message processing throughput.', D: 'FIFO queues have lower throughput limits than Standard — switching to FIFO reduces, not increases, maximum throughput.' } },
  { id: 'd2-msg-031', domain: 2, topics: ['EventBridge', 'input transformation'], type: 'single', stem: 'An EventBridge rule receives a complex event object. Only specific fields are needed by the Lambda target. Solution?', options: [{ id: 'A', text: 'Configure Lambda to extract needed fields from the full event object' }, { id: 'B', text: 'EventBridge input transformer — transforms and filters the event payload before delivery to Lambda' }, { id: 'C', text: 'EventBridge filter policy — removes unwanted fields from the event before matching' }, { id: 'D', text: 'Use Step Functions to extract and transform event fields before invoking Lambda' }], correct: ['B'], explanation: 'EventBridge input transformer: define an input path (JSONPath selectors) and an input template. EventBridge transforms the event before delivery — Lambda receives only the needed fields. No Lambda code change needed.', distractors: { A: 'Lambda extraction works but wastes Lambda compute on payload parsing — input transformer does this at the EventBridge layer.', C: 'EventBridge filter policy controls which events match a rule — it does not transform the event payload.', D: 'Step Functions orchestration adds complexity — input transformer is a native EventBridge feature.' } },
  { id: 'd2-msg-032', domain: 2, topics: ['SQS', 'access policy'], type: 'single', stem: 'Lambda in Account B must read from an SQS queue in Account A. What configuration is needed?', options: [{ id: 'A', text: 'SQS queues only work within a single account — cross-account queue access is not supported' }, { id: 'B', text: 'Queue policy on SQS in Account A allowing Account B Lambda role; Lambda role has sqs:ReceiveMessage on queue ARN' }, { id: 'C', text: 'Create a VPC peering connection between Account A and Account B for private queue access' }, { id: 'D', text: 'SQS queue in Account A must be replicated to Account B — use S3 replication for queue content' }], correct: ['B'], explanation: 'SQS cross-account access: (1) add a queue policy on the source queue allowing the cross-account role; (2) add IAM permissions to the Lambda role to call sqs:ReceiveMessage. Both sides must allow the access.', distractors: { A: 'SQS fully supports cross-account access via queue policies — it is not limited to same-account use.', C: 'SQS is an AWS managed API service — VPC peering is not needed for cross-account SQS access.', D: 'SQS content replication does not exist — cross-account queue policies provide direct access.' } },
  { id: 'd2-msg-033', domain: 2, topics: ['EventBridge', 'event bus', 'third-party'], type: 'single', stem: 'A Zendesk SaaS application must publish events directly to EventBridge for automated ticket processing. How?', options: [{ id: 'A', text: 'Set up a webhook from Zendesk to API Gateway, which forwards to EventBridge' }, { id: 'B', text: 'EventBridge Partner Event Sources — Zendesk and 100+ SaaS partners publish directly to EventBridge' }, { id: 'C', text: 'Configure an SNS topic as a Zendesk webhook target; SNS triggers EventBridge' }, { id: 'D', text: 'SaaS events must go through a custom Lambda integration — no direct SaaS-to-EventBridge connection exists' }], correct: ['B'], explanation: 'EventBridge Partner Event Sources: third-party SaaS providers (Zendesk, Datadog, Stripe, etc.) publish events directly to a dedicated partner event bus. No custom integration needed — subscribe by creating a matching event bus.', distractors: { A: 'API Gateway webhook integration works but adds infrastructure — Partner Event Sources provide direct native integration.', C: 'SNS intermediary adds complexity — Partner Event Sources publish directly to EventBridge without intermediaries.', D: 'Partner Event Sources enable direct SaaS-to-EventBridge connection — custom Lambda is not required.' } },
  { id: 'd2-msg-034', domain: 2, topics: ['SQS', 'cost optimization'], type: 'single', stem: 'An application sends 100 million SQS API calls per day. Primary cost lever?', options: [{ id: 'A', text: 'Switch to SQS FIFO — FIFO queues have lower per-request pricing' }, { id: 'B', text: 'Use SendMessageBatch and ReceiveMessage batch size 10 — reduces API calls by up to 10x' }, { id: 'C', text: 'Migrate to Amazon MQ — lower API call pricing for high-volume messaging' }, { id: 'D', text: 'Enable SQS message compression — compressed messages cost less per API call' }], correct: ['B'], explanation: 'SQS pricing: $0.40 per million requests. Batching 10 messages per call reduces 100M calls to 10M calls — $40/day savings vs $4/day with batching. Batching is the primary cost optimization for SQS.', distractors: { A: 'SQS FIFO costs the same per request as Standard — no pricing advantage for high volume.', C: 'Amazon MQ is for existing AMQP/MQTT workloads — migrating for cost alone adds complexity.', D: 'SQS does not compress messages or reduce cost based on message content.' } },
  { id: 'd2-msg-035', domain: 2, topics: ['SNS', 'subscription filter', 'attribute'], type: 'single', stem: 'An SNS topic publishes messages with attribute environment=prod and environment=dev. A subscriber should only receive production messages. Configuration?', options: [{ id: 'A', text: 'Create two SNS topics — one for prod and one for dev' }, { id: 'B', text: 'Set a subscription filter policy: {\"environment\": [{\"prefix\": \"prod\"}]} on the production subscriber' }, { id: 'C', text: 'Add an IAM policy on the subscriber that restricts to environment=prod messages' }, { id: 'D', text: 'Configure message routing in the publisher — send prod messages to the production subscriber directly' }], correct: ['B'], explanation: 'SNS subscription filter policy: JSON conditions on message attributes. For environment=prod, set filter: {"environment": ["prod"]}. The subscriber only receives messages where environment attribute equals prod.', distractors: { A: 'Separate topics work but lose the single-topic publish simplicity — filter policies achieve routing without multiple topics.', C: 'IAM policies control API access — they cannot filter SNS message content.', D: 'Publisher routing creates coupling — filter policies keep the publisher simple with per-subscriber filtering.' } },
  { id: 'd2-msg-036', domain: 2, topics: ['SQS', 'temporary queue'], type: 'single', stem: 'A microservice needs a reply queue per request for synchronous request-reply over SQS. Best approach?', options: [{ id: 'A', text: 'Create one SQS queue per request and delete it after the reply — maximally isolated' }, { id: 'B', text: 'Use SQS Temporary Queue client library — creates virtual queues multiplexed on a single physical queue' }, { id: 'C', text: 'Include a replyTo correlation ID in the message — consumer filters replies from a shared queue' }, { id: 'D', text: 'Use API Gateway for synchronous request-reply — SQS is inherently asynchronous' }], correct: ['B'], explanation: 'Temporary Queue client (SQS): virtual queues are multiplexed on one physical queue. Each request gets a virtual queue URL — no SQS queue creation API calls, no cost per virtual queue. Efficient request-reply pattern.', distractors: { A: 'Creating a physical queue per request has creation latency and costs — virtual queues via Temporary Queue Client are more efficient.', C: 'Shared queue with correlation ID works but requires all consumers to process all replies and discard non-matching ones.', D: 'SQS request-reply is a valid async pattern — Temporary Queue Client makes it efficient without API Gateway.' } },
  { id: 'd2-msg-037', domain: 2, topics: ['EventBridge', 'Lambda', 'retry'], type: 'single', stem: 'An EventBridge rule triggers Lambda. Lambda returns a 500 error. How many times does EventBridge retry?', options: [{ id: 'A', text: '0 times — Lambda errors are not retried by EventBridge' }, { id: 'B', text: '2 times — EventBridge retries Lambda failures with exponential backoff, up to 24 hours total' }, { id: 'C', text: '3 times — EventBridge always retries exactly 3 times before giving up' }, { id: 'D', text: 'Unlimited retries — EventBridge retries Lambda until it succeeds' }], correct: ['B'], explanation: 'EventBridge retries: up to 185 times over 24 hours with exponential backoff for Lambda target failures. Configure a DLQ on the EventBridge rule to capture events that exhaust all retries.', distractors: { A: 'EventBridge does retry Lambda failures — it retries up to 185 times over 24 hours.', C: 'EventBridge does not limit to exactly 3 retries — it retries over a configurable period up to 24 hours.', D: 'Retries are bounded — up to 185 attempts over 24 hours. After exhaustion, events go to the DLQ if configured.' } },
  { id: 'd2-msg-038', domain: 2, topics: ['SQS', 'scaling', 'consumer instances'], type: 'single', stem: 'How many SQS consumer instances should be added to maximize queue processing throughput?', options: [{ id: 'A', text: 'Always match consumers to queue depth — one consumer per message in flight' }, { id: 'B', text: 'Scale consumers until processing rate equals message arrival rate — monitor queue depth and age' }, { id: 'C', text: 'Up to 1,000 concurrent consumers per queue — SQS imposes a hard limit' }, { id: 'D', text: 'One consumer per availability zone — more consumers cause excessive API throttling' }], correct: ['B'], explanation: 'Scale consumers until ApproximateNumberOfMessagesVisible stabilizes at near-zero and ApproximateAgeOfOldestMessage is acceptably low. Consumer count is determined by demand — use Auto Scaling to adjust automatically.', distractors: { A: 'One consumer per in-flight message would require thousands of consumers for deep queues — batch processing is more efficient.', C: 'There is no 1,000 consumer hard limit per SQS queue — scale as needed.', D: 'More consumers do not cause API throttling — SQS scales to accommodate many concurrent pollers.' } },
  { id: 'd2-msg-039', domain: 2, topics: ['SNS', 'delivery retry policy'], type: 'single', stem: 'SNS fails to deliver to an HTTP endpoint. What is the default retry behavior?', options: [{ id: 'A', text: 'SNS gives up after 3 attempts with no retry delay' }, { id: 'B', text: 'SNS retries with exponential backoff over 23+ days — adjustable via delivery retry policies' }, { id: 'C', text: 'SNS retries 100 times at 1-second intervals then stops' }, { id: 'D', text: 'SNS has no retry mechanism for HTTP endpoints — implement retries at the application level' }], correct: ['B'], explanation: 'SNS HTTP/HTTPS delivery: configurable retry policy with exponential backoff. Default: 3 immediate retries, 2 pre-backoff retries, then exponential backoff phase, up to a max of ~100 total attempts over 23+ days.', distractors: { A: '3 attempts with no retry delay is not the default — the default includes backoff and many more retries.', C: '100 retries at 1-second intervals is not the default behavior — SNS uses exponential backoff.', D: 'SNS has a built-in retry policy for HTTP endpoints — application-level retries are not required.' } },
  { id: 'd2-msg-040', domain: 2, topics: ['SQS', 'max message retention'], type: 'single', stem: 'A batch job runs weekly. SQS messages sent Friday must still be available for processing Monday. Configuration?', options: [{ id: 'A', text: 'Default message retention (4 days) — messages are available for 4 days' }, { id: 'B', text: 'Set message retention period to at least 7 days — default 4 days would expire messages before Monday' }, { id: 'C', text: 'Enable long polling — preserves messages indefinitely until consumed' }, { id: 'D', text: 'Use SQS FIFO — FIFO queues have a 14-day maximum retention vs Standard\'s 4 days' }], correct: ['B'], explanation: 'SQS message retention: configurable from 1 minute to 14 days. Default is 4 days. For Friday-to-Monday retention (3 days), 4 days is sufficient — but set to 7 or more for safety margin.', distractors: { A: 'Default 4 days retains messages Friday through Tuesday — technically sufficient but setting 7 days adds safety margin.', C: 'Long polling changes how consumers wait for messages — it does not extend message retention.', D: 'Both Standard and FIFO support 14-day maximum retention — there is no difference in retention duration between them.' } },
  { id: 'd2-msg-041', domain: 2, topics: ['EventBridge', 'target types'], type: 'single', stem: 'Which of the following is NOT a valid EventBridge rule target?', options: [{ id: 'A', text: 'Lambda function' }, { id: 'B', text: 'SQS queue' }, { id: 'C', text: 'S3 object (direct PUT to an S3 key)' }, { id: 'D', text: 'Step Functions state machine' }], correct: ['C'], explanation: 'EventBridge targets include Lambda, SQS, SNS, Kinesis, Step Functions, ECS tasks, SSM Run Command, API Gateway, and more. Direct S3 PUT (to an S3 object key) is NOT a native EventBridge target — use Kinesis Firehose to write to S3.', distractors: { A: 'Lambda is a standard EventBridge target — commonly used for event-driven processing.', B: 'SQS queues are valid EventBridge targets — used for durable event delivery.', D: 'Step Functions state machines are valid EventBridge targets — used to start workflows on events.' } },
  { id: 'd2-msg-042', domain: 2, topics: ['SNS', 'email subscription', 'security'], type: 'single', stem: 'An SNS email subscription sends all messages to an unconfirmed email. Where do messages go?', options: [{ id: 'A', text: 'Messages are delivered to the unconfirmed email — confirmation is optional' }, { id: 'B', text: 'Messages are not delivered to unconfirmed subscriptions — they are discarded for that subscriber' }, { id: 'C', text: 'Messages queue up until the email is confirmed — then all queued messages are delivered' }, { id: 'D', text: 'Messages go to the SNS DLQ until the subscription is confirmed' }], correct: ['B'], explanation: 'SNS subscriptions in Pending Confirmation state do not receive messages. Email subscriptions require clicking a confirmation link. Until confirmed, all published messages are silently discarded for that subscription.', distractors: { A: 'Confirmation is required for email subscriptions — messages are not delivered before confirmation.', C: 'Messages are not queued waiting for confirmation — they are discarded. Confirming later does not deliver old messages.', D: 'SNS DLQs are configured per subscription for delivery failures — not for unconfirmed state.' } },
  { id: 'd2-msg-043', domain: 2, topics: ['SQS', 'FIFO', 'message group'], type: 'single', stem: 'An SQS FIFO queue processes orders. Orders for the same customer must be in strict order; different customers can be parallel. Configuration?', options: [{ id: 'A', text: 'Create one FIFO queue per customer — strict ordering per customer without cross-customer parallelism' }, { id: 'B', text: 'Use MessageGroupId set to the customer ID — messages with the same group ID are in strict order; different groups process in parallel' }, { id: 'C', text: 'Enable message deduplication — deduplication ensures ordering across all customers' }, { id: 'D', text: 'Use SQS Standard with sequence number attributes — consumers order messages client-side per customer' }], correct: ['B'], explanation: 'SQS FIFO MessageGroupId: messages with the same group ID are processed in strict FIFO order by one consumer. Different group IDs process concurrently. Setting GroupId=customerID achieves per-customer ordering with parallel processing.', distractors: { A: 'One queue per customer works but creates management complexity — MessageGroupId achieves this in a single queue.', C: 'Deduplication prevents duplicate processing — it does not enforce ordering within groups.', D: 'Standard queue offers no ordering guarantee — FIFO with MessageGroupId is the correct solution.' } },
  { id: 'd2-msg-044', domain: 2, topics: ['EventBridge', 'Schema Registry'], type: 'single', stem: 'EventBridge Schema Registry is enabled. What does it provide for event-driven development?', options: [{ id: 'A', text: 'Validates all events against registered schemas and rejects non-conforming events' }, { id: 'B', text: 'Discovers and stores event schemas; generates code bindings for Lambda functions in multiple languages' }, { id: 'C', text: 'Enforces IAM access control on event buses based on event schema' }, { id: 'D', text: 'Compresses events matching registered schemas for reduced EventBridge costs' }], correct: ['B'], explanation: 'EventBridge Schema Registry: auto-discovers event schemas, stores them in a registry, and generates code bindings (Java, Python, TypeScript) that represent event objects — simplifies event-driven development.', distractors: { A: 'Schema Registry does not validate or reject events — it is for discovery and code generation, not enforcement.', C: 'Schema Registry is not for IAM access control — IAM and resource policies control event bus access.', D: 'Schema Registry does not compress events — it provides schema metadata and code bindings.' } },
  { id: 'd2-msg-045', domain: 2, topics: ['SQS', 'SNS', 'EventBridge', 'selection'], type: 'multi', stem: 'Which TWO characteristics distinguish SQS from SNS?', options: [{ id: 'A', text: 'SQS is a pull-based queue (consumers poll); SNS is push-based (SNS delivers to subscribers)' }, { id: 'B', text: 'SQS messages are consumed by one consumer; SNS delivers to all subscribers simultaneously' }, { id: 'C', text: 'SQS supports message filtering; SNS does not support filtering of messages' }, { id: 'D', text: 'SQS messages are persistent; SNS messages are persistent for 14 days' }], correct: ['A', 'B'], explanation: 'Key differences: (1) SQS is pull-based (consumers poll); SNS is push-based (delivery to subscribers). (2) SQS messages are consumed by one consumer; SNS delivers to all subscribers (fan-out).', distractors: { C: 'SNS does support subscription filter policies — this statement is incorrect.', D: 'SQS messages are persistent (configurable retention up to 14 days); SNS messages are NOT stored — they are delivered in real-time with no persistence.' } },
]
